import{_ as d,b as u,c as l,d as t,t as q,C as c,u as i}from"./index-I5uTs6b4.js";const n={class:"level-page"},v={class:"level-content"},b={class:"level-title"},p={__name:"Level30",props:{id:{type:String,required:!0}},setup(e){const o=i();function s(){sessionStorage.setItem("skipIntro","1"),o.push("/")}return(f,a)=>(u(),l("div",n,[t("button",{class:"back-btn",onClick:s},"← Back to Index"),t("div",v,[t("h1",b,"SI-"+q(e.id),1),a[0]||(a[0]=c('<p class="level-name" data-v-b26e6fd0>&quot;超蓝之境&quot;</p><div class="section" data-v-b26e6fd0><h2 data-v-b26e6fd0>生存难度：ψ（精神危害）</h2><div class="difficulty" data-v-b26e6fd0><ul class="class-list" data-v-b26e6fd0><li data-v-b26e6fd0><span class="class-bullet entity" data-v-b26e6fd0></span> 实体数量：不定</li><li data-v-b26e6fd0><span class="class-bullet unstable" data-v-b26e6fd0></span> 层级稳定性：变化</li></ul></div></div><div class="section" data-v-b26e6fd0><h2 data-v-b26e6fd0>描述</h2><p data-v-b26e6fd0>该层级的主要区域有着类似平原的地理环境，面积约为 40 万平方千米。流浪者能且仅能通过&quot;门&quot;进入该层级。流浪者进入&quot;超蓝之境&quot;时，首先映入眼帘的便是一望无际的蔚蓝天空，本层级因此得名&quot;超蓝之境&quot;。除此之外则是绵延不绝的草原，其中点缀着些许人类活动的痕迹：或是早已报废的汽车，或是分崩离析的柏油马路，或是孤零零的破碎楼房。</p><p data-v-b26e6fd0>流浪者进入本层级时，时间通常表现为&quot;白天&quot;。此时层级内基本观测不到活动的实体，但到了<strong data-v-b26e6fd0>&quot;晚上&quot;</strong>，原本寂静无声的平原便会立马变得&quot;热闹&quot;起来。在此层级中游荡着许多实体，它们的外表会根据流浪者的主观意识发生改变。若流浪者不幸遭遇了本层级的实体，它们会&quot;窃取&quot;流浪者的记忆，并使自己幻化成为被流浪者抱有强烈情感的人或物。</p><p data-v-b26e6fd0>流浪者在遭受本层级实体的精神侵害时，通常常识会受到影响。死者苏生不会令其感到惊讶，神话生物也不是不能出现。最终，流浪者会因为沉溺于自己的情感，投入实体的&quot;怀抱&quot;……部分意志坚定或&quot;灵感&quot;较高的流浪者在接触本层级实体时，能够发现其异常之处，并自主脱离实体影响。</p><p data-v-b26e6fd0>幸存者可在本层级内找到现成的&quot;门&quot;，也可以自己创造&quot;门&quot;。发现并找到&quot;打开&quot;它们的方式，即可切入其他层级，且有极小概率可切回前室。</p></div><section class="sub-level dead-zone" data-v-b26e6fd0><div class="sub-tag dead-tag" data-v-b26e6fd0>子层级</div><p class="sub-name" data-v-b26e6fd0>&quot;彼岸&quot;</p><p data-v-b26e6fd0>在实体影响下完全失去理智的流浪者，会被送入&quot;彼岸&quot;。&quot;彼岸&quot;被描述为本层级的最深处或&quot;世界的尽头&quot;。流浪者进入&quot;彼岸&quot;时，往往身处一片漫长的海岸线，脚下是普通的沙滩，身后是并不高的防波堤。眼前的海洋与蔚蓝的天空融为一体。眼前的&quot;蔚蓝&quot;也具有本层级其他实体的能力，会扩大流浪者心中的情感，暗示每一位来到此处的流浪者进入其中。倘若流浪者跟从指引走入了&quot;蔚蓝&quot;，则会被本层级永远吞噬。若流浪者在进入&quot;彼岸&quot;后恢复理智，抵挡住了&quot;蔚蓝&quot;的呼唤，即可在登上堤坝后，通过海之家里的&quot;门&quot;离开。</p></section>',4))])]))}},_=d(p,[["__scopeId","data-v-b26e6fd0"]]);export{_ as default};
